import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"WebIDL Cross-Spec includes — Supplementary Mixin Specs","description":"","frontmatter":{"title":"WebIDL Cross-Spec `includes` — Supplementary Mixin Specs","type":"adr","date":"2026-10-28T00:00:00.000Z","status":"accepted","status_note":"Accepted."},"headers":[],"relativePath":"web/project/adrs/0121-webidl-cross-spec-includes.md","filePath":"vendored/web/project/adrs/0121-webidl-cross-spec-includes.md"}'),a={name:`web/project/adrs/0121-webidl-cross-spec-includes.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0121-webidl-cross-spec-includes-—-supplementary-mixin-specs" tabindex="-1">ADR-0121: WebIDL Cross-Spec <code>includes</code> — Supplementary Mixin Specs <a class="header-anchor" href="#adr-0121-webidl-cross-spec-includes-—-supplementary-mixin-specs" aria-label="Permalink to “ADR-0121: WebIDL Cross-Spec includes — Supplementary Mixin Specs”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>WHATWG/W3C specs routinely apply <code>X includes Y</code> where <code>Y</code> is an <code>interface mixin</code> declared in a <em>different</em> spec. Concretely, <code>encoding.idl</code> declares:</p><pre><code>TextDecoderStream includes GenericTransformStream;
TextEncoderStream includes GenericTransformStream;
</code></pre><p>but <code>GenericTransformStream</code> lives in <code>streams.idl</code>. The WebIDL backend (<a href="./0113-handl-sdkgen-webidl-js.html">ADR-0113</a>) resolved <code>includes</code> only against mixins in the same file, so cross-spec references surfaced as diagnostics (<code>includes: mixin GenericTransformStream not found</code>) and the generated records silently lacked the grafted members.</p><p>Two designs were considered:</p><ol><li><strong>Multi-spec generation</strong> — parse N idl files into one <code>SdkgenModule</code>. Merges unrelated surfaces into a single package and breaks the <code>&lt;spec-stem&gt;</code> → package-name convention (which stem wins?).</li><li><strong>Supplementary mixin specs</strong> — supplementary files contribute <em>only</em> mixin definitions to <code>includes</code> resolution; their interfaces, records, typedefs, and constants are not emitted.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Supplementary mixin specs, declared in the spec&#39;s <code>.sdkgen.yaml</code>:</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#888888;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;">#</span><span style="--shiki-dark:#BBBBBB;--shiki-dark-font-style:italic;--shiki-light:#62687b;--shiki-light-font-style:inherit;"> handl-packages/generated/encoding.sdkgen.yaml</span></span>
<span class="line"><span style="--shiki-dark:#B3FF66;--shiki-light:#11782a;">includes</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">:</span></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">  -</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;"> streams.idl</span></span></code></pre></div><ul><li><code>WebIdlConfig.includes: Vec&lt;String&gt;</code> — paths relative to the config file&#39;s directory (same reproducibility convention as the C backend&#39;s <code>headers:</code> overrides).</li><li><code>WebIdlBackend::add_include_spec(path)</code> registers each path; during <code>parse_header</code> the file is parsed and its <code>AstDef::Mixin</code> defs are added to the graft map. Primary-spec mixins win on a name collision.</li><li>Diagnostics are preserved: supplementary parse diagnostics are tagged with the file path, unreadable files and still-missing mixins report exactly as before.</li><li>Emission granularity is unchanged: one spec → one package. Encoding gains <code>readable</code>/<code>writable</code> on <code>TextDecoderStream</code>/<code>TextEncoderStream</code>; <code>streams.idl</code> types (<code>ReadableStream</code>, <code>WritableStream</code>) continue to map to <code>Handle</code> — no foreign records are pulled in.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>encoding.sdkgen.yaml</code> lists <code>streams.idl</code>; the generated <code>TextDecoderStream</code>/<code>TextEncoderStream</code> records are now complete.</li><li>Adding a spec that references foreign mixins requires an <code>includes:</code> entry — explicit, grep-able, and reproducible rather than ambient multi-file merging.</li><li>Because spec inputs (<code>*.idl</code>/<code>*.webidl</code>) are gitignored, the <code>includes:</code> paths are documentation of the required fetch set, not vendored references.</li></ul><p>Refs: <code>plugin-sdkgen-backend-webidl</code> (<code>includes_resolve_across_specs</code> test), <code>plugin-ext-sdkgen</code> CLI wiring.</p>`,14)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};